/**
 * engine-server/pipeline/safety-gate.ts — 安全基线运行时门控（V1.2 第二阶段）
 *
 * 6 条 SB (Safety Baseline) 规则，在 Agent 工具调用前执行硬阻断。
 * 对接 engine-server 管道：BlueprintDTO 生成后，在 Agent 安装前执行安全校验。
 *
 * 规则清单：
 * SB-01: 工具调用权限边界 — Agent 不能越权访问不属于它角色的工具
 * SB-02: 信息泄露防护 — Agent 不能将内部协议细节暴露给外部
 * SB-03: 决策权限制 — Governance 层 L3 角色的否决权不可被 L2 绕过
 * SB-04: 熔断机制 — 连续 3 次失败自动挂起，等待人工决策
 * SB-05: 禁言机制 — 恶意/有害输出自动阻断并记录
 * SB-06: 溯源徽章 — 每次工具调用记录发起 Agent + 决策链
 * SB-07: S-02 复述确认 — 高风险 Agent 必须在审批链注册，强制人工确认
 *
 * @packageDocumentation
 */
import type { BlueprintDTO } from '../types';
export type SafetyRuleId = 'SB-01' | 'SB-02' | 'SB-03' | 'SB-04' | 'SB-05' | 'SB-06' | 'SB-07';
export interface SafetyRuleResult {
    ruleId: SafetyRuleId;
    ruleName: string;
    passed: boolean;
    severity: 'error' | 'warning' | 'info';
    detail: string;
    /** 阻断原因（severity=error 时） */
    blockReason?: string;
}
export interface SafetyGateResult {
    /** 是否全部通过 */
    passed: boolean;
    /** 是否有硬阻断 */
    blocked: boolean;
    /** 各规则结果 */
    rules: SafetyRuleResult[];
    /** 阻断摘要 */
    summary: string;
    /** 审计日志条目 */
    auditEntries: string[];
}
/**
 * 对生成的 BlueprintDTO 执行安全基线硬阻断检查。
 * 应在 Blueprint 组装完成后、返回给用户前调用。
 */
export declare function runSafetyGates(blueprint: BlueprintDTO): SafetyGateResult;
/**
 * 获取熔断配置（供 Protocol Engine 运行时消费）
 */
export declare function getCircuitBreakerConfig(): {
    maxConsecutiveFailures: number;
    cooldownMinutes: number;
    requiredHumanApprovalAfter: number;
};
/**
 * 获取有害内容检测模式（供运行时消息过滤使用）
 */
export declare function getHarmfulPatterns(): RegExp[];
